/*
 * A307527  Odd terms in A305236.
 * https://oeis.org/A307527
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 none, u16 none, u32 n <= 18, u64 n <= 156, u128 n <= 156,
 *            big any n
 * Helpers:   build_primes_upto, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation: a(n) = n-th smallest integer of the form
 * p^e * ((p-1)*p^(e-1)+1), where p is an odd prime, e ≥ 2, and
 * ((p-1)*p^(e-1)+1) is prime.  The sequence is generated by
 * enumerating all such numbers up to UINT64_MAX, sorting them, and
 * returning the n‑th element.  The function is memoised so that
 * repeated calls are O(1). */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/is_prime_big.h"      /* bool is_prime_big(seq_t n); */
#include "../utils/build_primes_upto.h" /* void build_primes_upto(idx_t limit,
                                         uint64_t **out, size_t *cnt); */

static int seq_compare(const void *a, const void *b)
{
    const seq_t *x = (const seq_t *)a;
    const seq_t *y = (const seq_t *)b;
    if (*x < *y) return -1;
    if (*x > *y) return 1;
    return 0;
}

static seq_t *seq_buf      = NULL; /* sorted unique terms up to a limit */
static size_t seq_len      = 0;    /* number of stored terms */
static bool   initialized  = false;

/* Populate seq_buf with all terms <= UINT64_MAX. */
static void init_sequence(void)
{
    if (initialized) return;
    initialized = true;

    /* Limit for stored terms – keep within 64‑bit range. */
    const seq_t LIMIT = (seq_t)UINT64_MAX;

    /* Bound for primes – sufficient to generate all terms below LIMIT. */
    const idx_t PRIME_BOUND = 2000000;

    uint64_t *primes = NULL;
    size_t primes_cnt = 0;
    build_primes_upto(PRIME_BOUND, &primes, &primes_cnt);

    size_t cap = 1024;
    seq_t *cand = (seq_t *)malloc(cap * sizeof(seq_t));
    if (!cand) {
        free(primes);
        return;
    }
    size_t cand_cnt = 0;

    for (size_t pi = 0; pi < primes_cnt; ++pi) {
        seq_t p = (seq_t)primes[pi];
        if (p == 2) continue;                /* skip the even prime */

        /* pow_e_minus_1 = p^(e-1), start with e = 2 => pow_e_minus_1 = p */
        seq_t pow_e_minus_1 = p;
        while (pow_e_minus_1 <= LIMIT / p) {
            seq_t pow_e = pow_e_minus_1 * p;              /* p^e          */
            seq_t q   = (seq_t)(p - 1) * pow_e_minus_1 + 1;   /* (p-1)p^(e-1)+1 */

            /* Avoid overflow when computing the product. */
            if (pow_e > 0 && q > 0 && pow_e <= LIMIT / q) {
                seq_t v = pow_e * q;
                if (is_prime_big(q)) {
                    if (cand_cnt == cap) {
                        cap <<= 1;
                        seq_t *tmp = (seq_t *)realloc(cand, cap * sizeof(seq_t));
                        if (!tmp) { free(cand); free(primes); return; }
                        cand = tmp;
                    }
                    cand[cand_cnt++] = v;
                }
            }
            /* Prepare for next exponent.  pow_e will be p^(e) in the next
             * iteration, which becomes p^(e-1) when e increments. */
            pow_e_minus_1 = pow_e;
        }
    }
    free(primes);

    /* Sort and deduplicate candidates. */
    qsort(cand, cand_cnt, sizeof(seq_t), seq_compare);

    seq_buf = (seq_t *)malloc(cand_cnt * sizeof(seq_t));
    if (!seq_buf) { free(cand); return; }

    seq_len = 0;
    for (size_t i = 0; i < cand_cnt; ++i) {
        if (i == 0 || cand[i] != cand[i - 1]) {
            seq_buf[seq_len++] = cand[i];
        }
    }
    free(cand);
}

/* Required public interface. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;       /* undefined; protect */
    init_sequence();
    if ((size_t)n > seq_len) return 0;  /* out of range */
    return seq_buf[n - 1];      /* sequence is 1‑indexed */
}
